# Regular expressions for SemVer 2.0.0 components
# MAJOR, MINOR, PATCH: Must be non-negative integers without leading zeros (unless it is '0').
# Pattern for numeric identifiers (0-9).
NUMERIC_IDENTIFIER = r"(?:0|[1-9][0-9]*)"
# Pattern for alphanumeric identifiers (letters, digits, hyphen).
ALPHANUMERIC_IDENTIFIER = r"[0-9a-zA-Z-]+"

# Full SemVer regex pattern:
# ^(MAJOR)\.(MINOR)\.(PATCH)(?:-([0-9a-zA-Z.-]+))?(?:\+([0-9a-zA-Z.-]+))?$
# Note: We use a slightly more permissive regex here and rely on manual checks for leading zeros and empty identifiers.
SEMVER_REGEX = re.compile(
    r"^([0-9]+)\.([0-9]+)\.([0-9]+)"  # Major.Minor.Patch
    r"(?:-([0-9a-zA-Z.-]+))?"           # Optional Pre-release
    r"(?:\+([0-9a-zA-Z.-]+))?$"
)

def _validate_identifier(identifier: str, is_numeric: bool) -> bool:
    """Validates a single pre-release or build identifier."""
    if not identifier: 
