                num_o = int(o_id)
                if num_s < num_o: return -1
                if num_s > num_o: return 1
            elif is_s_num and not is_o_num: 
                # Numeric is lower than alphanumeric
                return -1 
            elif not is_s_num and is_o_num: 
                # Alphanumeric is higher than numeric
                return 1
            else: 
                # Alphanumeric comparison (ASCII order)
                if s_id < o_id: return -1
                if s_id > o_id: return 1

