def _normalize_version_string(constraint_str: str) -> Version:
    """Parses a constraint string (which may be partial) into a fully specified Version object (no prerelease/build)."""

    parts = [p for p in constraint_str.split('.') if p]

    if not parts:
        raise ValueError("Constraint segment cannot be empty.")

    try:
        if len(parts) == 1:
            major = int(parts[0])
            minor = 0
            patch = 0
        elif len(parts) == 2:
            major = int(parts[0])
            minor = int(parts[1])
            patch = 0
        elif len(parts) == 3:
            major = int(parts[0])
            minor = int(parts[1])
            patch = int(parts[2])
        else:
            raise ValueError("Too many components in version constraint.")
    except ValueError:
        raise ValueError(f"Constraint segment '{constraint_str}' contains non-integer parts.")

    # Check for leading zeros in core parts
    if (len(parts[0]) > 1 and parts[0].startswith('0')) or \
       (len(parts) > 1 and len(parts[1]) > 1 and parts[1].startswith('0')) or \
       (len(parts) == 3 and len(parts[2]) > 1 and parts[2].startswith('0')):
        raise ValueError("Constraint segment has a leading zero in a core part.")

    # Per rules, partial versions cannot have pre-release or build parts
    return Version(major, minor, patch, tuple(), tuple(), f"{major}.{minor}.{patch}")

def _calculate_caret_range(base_version: Version) -> Tuple[Version, Version]:
    """Calculates the inclusive lower bound and exclusive upper bound for a ^V constraint."""
    major, minor, patch = base_version.major, base_version.minor, base_version.patch

    if major == 0 and minor == 0 and patch == 0:
        # ^0.0.0 is >=0.0.0 <0.0.1 (effectively, only 0.0.0)
        lower = base_version
        upper = Version(0, 0, 1, tuple(), tuple(), "0.0.1")
        return lower, upper

    if major == 0: # e.g., ^0.2.3 -> >=0.2.3 <0.3.0
        lower = base_version
        upper = Version(0, minor + 1, 0, tuple(), tuple(), f"0.{minor+1}.0")
        return lower, upper

    # Standard case: ^1.2.3 -> >=1.2.3 <2.0.0
    lower = base_version
    upper = Version(major + 1, 0, 0, tuple(), tuple(), f"{major+1}.0.0")
    return lower, upper

