def satisfies(version: Version, spec: str) -> bool:
    """Checks if the version satisfies all comparators in the spec."""
    if not spec: 
        raise ValueError("Specification string 'spec' cannot be empty.")

    comparators = spec.split()

    for comparator in comparators:
        # Determine operator and version segment
        operator = ''
        constraint_str = comparator

