        elif comparator.startswith('<='): operator = '<=' ; constraint_str = comparator[2:]
        elif comparator.startswith('=='): operator = '==' ; constraint_str = comparator[2:]
        elif comparator.startswith('>'): operator = '>' ; constraint_str = comparator[1:]
        elif comparator.startswith('<'): operator = '<' ; constraint_str = comparator[1:]
        elif comparator.startswith('~'): operator = '~' ; constraint_str = comparator[1:]
        elif comparator.startswith('^'): operator = '^' ; constraint_str = comparator[1:]
        else: # Bare version means '='
