def lcs_length(a: list[str], b: list[str]) -> int:
    """Computes the length of the Longest Common Subsequence (LCS) of two lists of strings.

    Uses standard dynamic programming approach. Time and space complexity: O(m*n).
    """
    m = len(a)
    n = len(b)

    # Initialize DP table: dp[i][j] stores the length of LCS of a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                # Take the maximum LCS found by excluding one line from either sequence
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

