def search_rotated(a: list[int], x: int) -> int:
    """Searches for x in a list of distinct values that was sorted and then rotated.
    Returns the index of x, or -1 if not found. Runs in O(log n)."""
    if not a:
        return -1

    low = 0
    high = len(a) - 1

    while low <= high:
        mid = (low + high) // 2

        if a[mid] == x:
            return mid

        # Check if the left half is sorted
        if a[low] <= a[mid]:
            # Left half is sorted
            if a[low] <= x < a[mid]:
                # x is in the left sorted half
                high = mid - 1
            else:
                # x must be in the right (unsorted or sorted but doesn't match)
                low = mid + 1
        else:
            # Right half must be sorted
            if a[mid] < x <= a[high]:
                # x is in the right sorted half
                low = mid + 1
            else:
                # x must be in the left (unsorted or sorted but doesn't match)
                high = mid - 1

