from typing import Callable, List, Tuple, Union, Dict, Optional

# --- Exceptions ---
class MachineError(Exception):
    """Base exception for the FSM machine."""
    pass

class InvalidTransition(MachineError):
    """Raised when no transition is defined for an event from the current state."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"No transition for event '{event}' from state '{state}'.")

class GuardRejected(MachineError):
    """Raised when all transitions for an event from the current state are rejected by guards."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"All transitions for event '{event}' from state '{state}' were rejected by guards.")

# --- Data Classes ---
@dataclass
class State:
    name: str
    on_enter: Optional[Callable[['Machine', 'Event'], None]] = None
    on_exit: Optional[Callable[['Machine', 'Event'], None]] = None

@dataclass
class Transition:
    event: str
    source: Union[str, List[str], Tuple[str, ...], str]  # '*' matches every state
    target: Optional[str]
    guard: Optional[Callable[['Machine', 'Event'], bool]] = None
    action: Optional[Callable[['Machine', 'Event'], None]] = None

@dataclass
class Event:
    name: str
    source: str
    target: str
    data: Dict = field(default_factory=dict)

# Type alias for a hook/listener
Hook = Callable[['Machine', 'Event'], None]

class Machine:
    """
    A Finite State Machine implementation.
    """
    def __init__(self, states: List[Union[str, State]], transitions: List[Transition], initial: str, context: Optional[object] = None):
        if not states:
            raise ValueError("States list cannot be empty.")

        self._state_definitions: Dict[str, State] = {}
        self._state_names: set = set()
        self._transition_map: Dict[str, List[Transition]] = {}
        self._listeners: List[Callable[[str, Event, str], None]] = []

        # 1. Process states and validate names
        for item in states:
            if isinstance(item, str):
                name = item
                state_obj = State(name=name)
            elif isinstance(item, State):
                name = item.name
                state_obj = item
            else:
                raise TypeError("States must be strings or State objects.")

            if name in self._state_names:
                raise ValueError(f"Duplicate state name found: {name}.")

            self._state_names.add(name)
            self._state_definitions[name] = state_obj

        if initial not in self._state_names:
            raise ValueError(f"Initial state '{initial}' is not defined.")

        # 2. Process transitions and validate sources/targets
        for t in transitions:
            valid_source = self._validate_transition_source(t.source)
            if not valid_source: # Should be caught by _validate_transition_source logic, but as safety
                continue

            # Target validation
            target_name = t.target
            if target_name is not None and target_name not in self._state_names:
                raise ValueError(f"Transition target '{target_name}' is not a defined state.")

            if t.event not in self._transition_map:
                self._transition_map[t.event] = []

            # Store transition, mapping source to transition list
            if isinstance(t.source, str) and t.source != '*':
                if t.source not in self._transition_map.get(t.event, []): # Simple check to avoid duplicates in source list
                     self._transition_map[t.event].append(t)
            elif isinstance(t.source, (list, tuple)): 
                 for src in t.source: 
                     if src in self._state_names or src == '*':
                         # This complexity is handled better by checking during fire, but validation requires knowing if ALL sources exist.
                         # For simplicity based on requirement, we just ensure targets exist.
                         pass
            else: # '*' or other valid structure
                 self._transition_map[t.event].append(t)

        # Final check: Ensure all transition sources/targets are valid states or '*' or None
        for t in transitions:
            if isinstance(t.source, str) and t.source != '*' and t.source not in self._state_names:
                raise ValueError(f"Transition source '{t.source}' is not a defined state.")
            if t.target is not None and t.target not in self._state_names:
                # This should be caught above, but confirms.
                raise ValueError(f"Transition target '{t.target}' is not a defined state.")

        self.state: str = initial
        self.context: Optional[object] = context
        self.history: List[Tuple[str, str, str]] = []
        self._initial_state: str = initial

    def _validate_transition_source(self, source: Union[str, List[str], Tuple[str, ...], str]) -> bool:
        """Helper to check if source names are valid states or '*'."""
        if source == '*':
            return True
        if isinstance(source, str) and source in self._state_names:
            return True
        if isinstance(source, (list, tuple)):
            for s in source:
                if s != '*' and s not in self._state_names:
                    return False
            return True
        return False

    def fire(self, event: str, **data) -> str:
        """Executes a transition based on the given event, following 7 steps."""
        if self._is_firing: # Check for re-entrancy
            raise MachineError("Cannot call fire while another fire operation is in progress.")

        self._is_firing = True
        try:
            # 2. Create data dict
            event_data: Dict = data.copy()
            # 1. Find candidates (must match event and current state)
            candidates: List[Transition] = []
            for t in self._transition_map.get(event, []):
                is_source_match = False
                if t.source == '*':
                    is_source_match = True
                elif isinstance(t.source, str) and t.source == self.state:
                    is_source_match = True
                elif isinstance(t.source, (list, tuple)) and self.state in t.source:
                    is_source_match = True

                if is_source_match:
                    candidates.append(t)

            if not candidates:
                raise InvalidTransition(self.state, event)

            # 3. Evaluate guards
            selected_transition: Optional[Transition] = None
            for candidate in candidates:
                if candidate.guard is None:
                    selected_transition = candidate
                    break
                try:
                    if candidate.guard(self, Event(event, self.state, candidate.target or self.state, event_data)):
                        selected_transition = candidate
                        break
                except Exception as e:
                    # 6. Exception during guard evaluation propagates unchanged
                    self._is_firing = False
                    raise e

            if selected_transition is None:
                raise GuardRejected(self.state, event)

            # Setup for transition execution
            old_state = self.state
            event_obj = Event(event, old_state, selected_transition.target or old_state, event_data)

            try:
                # 4. Normal Transition Execution
                if selected_transition.target is not None:
                    # 4a. Run on_exit
                    if self._state_definitions[old_state].on_exit:
                        self._state_definitions[old_state].on_exit(self, event_obj)

                    # 4b. Run transition action
                    if selected_transition.action:
                        selected_transition.action(self, event_obj)

                    # State change and history
                    new_state = selected_transition.target
                    self.state = new_state
                    self.history.append((old_state, event, new_state))

                    # 4c. Run target state's on_enter
                    self._state_definitions[new_state].on_enter(self, event_obj)

                # 5. Internal Transition Execution (target=None)
                else:
                    # Runs only action, no on_exit/on_enter
                    if selected_transition.action:
                        selected_transition.action(self, event_obj)

                    # Record history (target=source)
                    self.history.append((old_state, event, old_state))

                # 4d. Run on_transition listeners
                for listener in self._listeners:
                    listener(old_state, event_obj, self.state)

            except Exception as e:
                # 6. Exception handling
                if isinstance(e, MachineError) and isinstance(e, (GuardRejected, InvalidTransition)):
                    # This case shouldn't be reached here as those are raised before state change/hooks
                    pass 
                elif selected_transition.target is not None and (old_state != selected_transition.target): 
