                self._is_firing = False
                return self.state

        except MachineError:
            # Re-raise specific FSM errors (InvalidTransition, GuardRejected)
            self._is_firing = False
            raise
        except Exception:
            # Ensure re-entrancy flag is reset if any other unexpected error occurs
            self._is_firing = False
            raise

    def can_fire(self, event: str, **data) -> bool:
        """Checks if a transition would be taken, evaluating only guards."""
        # 1. Find candidates (same logic as fire)
        candidates: List[Transition] = []
        for t in self._transition_map.get(event, []):
            is_source_match = False
            if t.source == '*':
                is_source_match = True
            elif isinstance(t.source, str) and t.source == self.state:
                is_source_match = True
            elif isinstance(t.source, (list, tuple)) and self.state in t.source:
                is_source_match = True

            if is_source_match:
                candidates.append(t)

        if not candidates:
            return False

        # 2. Evaluate guards (no other hooks run)
        for candidate in candidates:
            if candidate.guard is None:
                return True
            try:
                if candidate.guard(self, Event(event, self.state, candidate.target or self.state, data)):
                    return True
            except Exception:
                # Guard side effects are prohibited, but if one throws, we treat it as failure to proceed safely
                pass

        return False

    def available_events(self) -> List[str]:
        """Returns sorted, de-duplicated names of events that can fire from the current state."""
        available = set()
        for t in self._transition_map.get(self.state, []):
             # Ignoring guards for this check
            available.add(t.event)
        return sorted(list(available))

    def on_transition(self, listener: Callable[[str, Event, str], None]):
        """Adds a listener that gets called after a successful transition."""
        self._listeners.append(listener)

    def reset(self):
        """Resets the machine to the initial state without running hooks."""
        self.state = self._initial_state
        self.history = []
        self._is_firing = False

    # --- Properties for easy access (not strictly required by task, but useful for context) ---
    @property
    def state(self) -> str:
        return self._state

    @state.setter
    def state(self, new_state: str):
        self._state = new_state

    @property
    def _is_firing(self) -> bool:
        return getattr(self, '_is_firing', False)

    @_is_firing.setter
    def _is_firing(self, value: bool):
        self._is_firing = value

