import re
from typing import Union, List, Dict, Any

# --- Error Values ---
class FormulaError(ValueError):
    """Raised for formula syntax or structural errors."""
    pass

class ErrorValue(str):
    """Represents an error state in a cell value."""
    pass

# --- AST Nodes ---
class NumberNode:
    def __init__(self, value: Union[int, float]):
        self.value = value

    def __repr__(self): return f"NumberNode({self.value})"

class RefNode:
    def __init__(self, name: str): # Name is already upper case
        self.name = name

    def __repr__(self): return f"RefNode('{self.name}')"

class BinaryOpNode:
    def __init__(self, op: str, left, right): # op is '+', '-', '*', '/'
        self.op = op
        self.left = left
        self.right = right

    def __repr__(self): return f"BinaryOpNode('{self.op}', {self.left}, {self.right})"

class UnaryOpNode:
    def __init__(self, op: str, operand): # op is '+', '-'
        self.op = op
        self.operand = operand

    def __repr__(self): return f"UnaryOpNode('{self.op}', {self.operand})"

# --- Parsing ---

# Regex for tokenization (allowing whitespace) based on grammar
TOKEN_SPECIFICATION = [ 
    ('NUMBER', r'        [0-9]+\.?[0-9]* '), # Digits [. digits] -- simplified to catch numbers
    ('REF', r'[a-zA-Z]+[0-9]+'), # letters digits
    ('LPAREN', r'\('), 
    ('RPAREN', r'\)'), 
    ('PLUS', r'\+'), 
    ('MINUS', r'\-'), 
    ('MUL', r'\*'), 
    ('DIV', r'\/'), 
    ('SKIP', r'[ \t\n]+'), 
    ('MISMATCH', r'.'),
]
TOKEN_REGEX = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPECIFICATION)

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self): return f"Token({self.type}, '{self.value}')"

def tokenize(text: str) -> List[Token]:
    tokens = []
    for mo in re.finditer(TOKEN_REGEX, text):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise FormulaError(f"Unexpected character: {value}")
        else:
            tokens.append(Token(kind, value))
    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def eat(self, expected_type: str): 
        token = self.current_token()
        if not token or token.type != expected_type:
            raise FormulaError(f"Expected {expected_type}, but got {token.type if token else 'EOF'}")
        self.pos += 1

    # Grammar implementation (Precedence Climbing / Pratt style simplified)

    def parse_primary(self) -> Union[NumberNode, RefNode, UnaryOpNode, tuple]:
        token = self.current_token()
        if not token:
            raise FormulaError("Incomplete expression: expected primary element.")

        if token.type == 'NUMBER':
            self.pos += 1
            try:
                val = float(token.value)
                if '.' not in token.value:
                    val = int(val)
                return NumberNode(val)
            except ValueError:
                raise FormulaError(f"Invalid number format: {token.value}")

        elif token.type == 'REF':
            self.pos += 1
            return RefNode(token.value)

        elif token.type == 'LPAREN':
            self.eat('LPAREN')
            expr = self.parse_expr(0) # Start parsing inside parentheses
            self.eat('RPAREN')
            return expr

        elif token.type == 'PLUS' or token.type == 'MINUS':
            # Handle unary signs
            op_token = token
            self.pos += 1
            operand = self.parse_primary()
            return UnaryOpNode(op_token.value, operand)

        else:
            raise FormulaError(f"Unexpected token in primary expression: {token.type} {token.value}")

    def parse_term(self, min_precedence: int) -> Union[NumberNode, RefNode, BinaryOpNode, UnaryOpNode]:
        left = self.parse_primary()

        while True:
            token = self.current_token()
            if not token:
                break

            precedence = self._get_precedence(token.type)
            if precedence < min_precedence:
                break

            op = token.type
            self.pos += 1

            if op in ('MUL', 'DIV'): # Multiplication/Division are left-associative
                right = self.parse_term(precedence + 1)
                left = BinaryOpNode(op.replace('MUL', '*').replace('DIV', '/'), left, right)
            else:
                # Should not happen if logic is correct, but handles general binary ops
                break 

        return left

    def parse_expr(self, min_precedence: int) -> Union[NumberNode, RefNode, BinaryOpNode, UnaryOpNode]:
        left = self.parse_term(min_precedence)

        while True:
            token = self.current_token()
            if not token:
                break

            precedence = self._get_precedence(token.type)
            if precedence < min_precedence:
                break

            op = token.type
            self.pos += 1

            # Addition/Subtraction are left-associative
            right = self.parse_expr(precedence + 1) # Note: using parse_expr here ensures correct left association
            left = BinaryOpNode(op.replace('PLUS', '+').replace('MINUS', '-'), left, right)

        return left

    def _get_precedence(self, token_type: str) -> int:
        if token_type in ('+', '-'): return 1
        if token_type in ('*', '/'): return 2
        return 0

    def parse(self) -> Union[NumberNode, RefNode, BinaryOpNode, UnaryOpNode]:
        # Start parsing at the lowest precedence (0)
        ast = self.parse_expr(0)
        if self.pos != len(self.tokens):
            raise FormulaError("Syntax error: extra tokens remaining after parsing.")
        return ast

# --- Public Interface Functions ---

def parse_formula(source: str) -> Union[NumberNode, RefNode, BinaryOpNode, UnaryOpNode]:
    if not source.strip():
        raise FormulaError("Formula input cannot be empty.")

    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()

def references(tree: Union[NumberNode, RefNode, BinaryOpNode, UnaryOpNode]) -> set[str]:
    referenced_names = set()

    if isinstance(tree, RefNode):
        return {tree.name}
    elif isinstance(tree, BinaryOpNode):
        referenced_names.update(references(tree.left))
        referenced_names.update(references(tree.right))
    elif isinstance(tree, UnaryOpNode):
        referenced_names.update(references(tree.operand))
    # NumberNode returns empty set
    return referenced_names

# --- Evaluation Logic ---

def _apply_op(op: str, left_val: Any, right_val: Any) -> Any:
    # Rule 3: Error propagation
    if isinstance(left_val, ErrorValue):
        return left_val
    if isinstance(right_val, ErrorValue):
        return right_val

    # Rule 3: Text on operand
    if isinstance(left_val, str) and left_val != '#ERROR!':
        return ErrorValue('#ERROR!')
    if isinstance(right_val, str) and right_val != '#ERROR!':
        return ErrorValue('#ERROR!')

    # All other cases are numeric (int/float) or potentially 'hi' (str)
    try:
        if op == '+':
            return left_val + right_val
        elif op == '-':
            return left_val - right_val
        elif op == '*':
            return left_val * right_val
        elif op == '/':
            if right_val == 0:
                return ErrorValue('#ERROR!')
