from typing import Any, Dict, List, Set, Union

class FormulaError(ValueError):
    """Raised when a formula is syntactically invalid or refers to invalid locations."""
    pass

# Type alias for cell values, including error types
CellValue = Union[int, float, str, None, 'ErrorValue']

class ErrorValue(str):
    """Represents a calculated error state in a cell."""
    pass

class FormulaErrorValue(ErrorValue):
    """Indicates a general calculation failure."""
    def __init__(self): super().__init__("#ERROR!")

class CycleErrorValue(ErrorValue):
    """Indicates a circular dependency."""
    def __init__(self): super().__init__("#CYCLE!")

# --- AST Node Definitions ---

# Base class for all nodes in the syntax tree
class FormulaNode:
    pass

class NumberNode(FormulaNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

class ReferenceNode(FormulaNode):
    def __init__(self, name: str): # name is expected to be upper-cased
        self.name = name

class UnaryOpNode(FormulaNode):
    def __init__(self, op: str, operand: FormulaNode): # op is '+' or '-'
        self.op = op
        self.operand = operand

class BinaryOpNode(FormulaNode):
    def __init__(self, op: str, left: FormulaNode, right: FormulaNode):
        self.op = op
        self.left = left
        self.right = right

# --- Parsing and Reference Extraction ---

# Placeholder for tokenization/parsing logic. A full parser implementation 
# is complex and omitted here as per instruction focus for this step.

def parse_formula(source: str) -> FormulaNode:
    """
    Parses the formula text (after '=') into a syntax tree.

    Raises:
        FormulaError: For empty input, grammar violations, unbalanced parentheses,
                      or out-of-bounds references.

    NOTE: This is a placeholder. A complete implementation requires a full LL(1) or LR parser.
    For this initial step, we assume a successful parse results in a placeholder structure.
    """
    if not source.strip():
        raise FormulaError("Formula source cannot be empty.")

    # Mocking a parse result for structure demonstration
    # In a real implementation, this would build the tree.
    print(f"[INFO] Parsing formula: {source}")
    return NumberNode(1) # Dummy successful parse

def references(tree: FormulaNode) -> Set[str]:
    """
    Recursively traverses the AST and returns a set of referenced cell names.
    """
    referenced = set()

    def _traverse(node: FormulaNode):
        if isinstance(node, ReferenceNode):
            referenced.add(node.name)
        elif isinstance(node, UnaryOpNode):
            _traverse(node.operand)
        elif isinstance(node, BinaryOpNode):
            _traverse(node.left)
            _traverse(node.right)
        # NumberNode has no references

    _traverse(tree)
    return referenced

# --- Evaluation Logic ---

# Forward declarations for type hinting
# We define the required types here, though the actual types are complex.

# Helper to handle error propagation based on Rule 3
def _combine_errors(op: str, left: CellValue, right: CellValue) -> CellValue:
    if isinstance(left, ErrorValue) or isinstance(right, ErrorValue):
        # Rule 3: If either is an error, the result is that error value (left if both)
        return left if isinstance(left, ErrorValue) else right

# Helper to determine resulting type for arithmetic operations
def _determine_type(left: CellValue, right: CellValue) -> Union[type, ErrorValue]:
    if isinstance(left, ErrorValue) or isinstance(right, ErrorValue):
        return ErrorValue()

    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        # Check if one is float to determine output type
        if isinstance(left, float) or isinstance(right, float):
            return float
        return int

    # If we reach here and they are not both numbers, it's an error in context
    # but for basic arithmetic, we assume types are checked upstream.
    return None


def evaluate(tree: FormulaNode, lookup: Dict[str, CellValue]) -> CellValue:
    """
    Computes the formula's value based on the AST and current cell lookups.
    """

    def _eval_node(node: FormulaNode) -> CellValue:
        if isinstance(node, NumberNode):
            return node.value

        elif isinstance(node, ReferenceNode):
            name = node.name
            value = lookup.get(name)

            # Rule 2: Reference handling
            if value is None: # Empty cell
                return 0
            if isinstance(value, str) and value == "": # Explicitly empty string might be treated as text, but None is 0
                 return 0
            # Rule 2: Formula that is only a reference returns text unchanged
            if isinstance(value, str) and not isinstance(value, ErrorValue):
                return value # Return text value
            return value

        elif isinstance(node, UnaryOpNode):
            operand_val = _eval_node(node.operand)
            op = node.op

            if isinstance(operand_val, ErrorValue):
                return operand_val

            # Handle unary negation
            if op == '-':
                return -operand_val
            # Handle unary plus (identity)
            return operand_val

        elif isinstance(node, BinaryOpNode):
            left_val = _eval_node(node.left)
            right_val = _eval_node(node.right)
            op = node.op

            if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
                return _combine_errors(op, left_val, right_val)

            # Rule 3: Text interaction
            left_is_text = isinstance(left_val, str) and not isinstance(left_val, ErrorValue)
