TOKEN_SPECIFICATION = [
    ('NUMBER', r'    [0-9]+\.?[0-9]*   '), # Numbers (handles integers and floats)
    ('REF', r'[a-zA-Z][a-zA-Z0-9]*'),                 # References (letters followed by digits/letters)
    ('OP', r'[\[\]\[\]\[\]\[\]]'),              # Operators: +, -, *, /, (, )
    ('SKIP', r'[ \t]+'),                             # Whitespace to skip
    ('MISMATCH', r'.')                                # Any other character
]

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value!r})'

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.tokens: List[Token] = []

    def tokenize(self) -> Iterator[Token]:
        tokens_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPECIFICATION)
        for mo in re.finditer(tokens_regex, self.text, re.DOTALL):
            kind = mo.lastgroup
            value = mo.group(kind)

            if kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise FormulaError(f"Invalid character '{value}' in formula.")
            elif kind == 'NUMBER':
                yield Token('NUMBER', value)
            elif kind == 'REF':
                # Reference names are case-insensitive, so store as found, but validation handles casing.
                yield Token('REF', value)
            elif kind == 'OP':
                # Handle operators (+, -, *, /, (, ))
                if value in ('+', '-', '*', '/', '(', ')'):
                    yield Token('OP', value)
                else:
                     # This branch should ideally not be hit if TOKEN_SPECIFICATION is perfect
                    raise FormulaError(f"Unrecognized operator token: {value}")

# --- Parser ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def advance(self):
        self.pos += 1

    def expect(self, expected_type: str, expected_value: str = None):
        token = self.current_token()
        if not token or token.type != expected_type:
            raise FormulaError(f"Expected token type {expected_type}, but got {token.type if token else 'EOF'}.")
        if expected_value and token.value != expected_value:
             raise FormulaError(f"Expected token value '{expected_value}', but got '{token.value}'.")
        self.advance()

    # Grammar implementation functions

    # expr := term {(+ | -) term}
    def parse_expression(self) -> FormulaNode:
        node = self.parse_term()
        while self.current_token() and self.current_token().type == 'OP' and self.current_token().value in ('+', '-'):
            op = self.current_token().value
            self.advance()
            right = self.parse_term()
            node = BinaryOpNode(op, node, right)
        return node

    # term := unary {(* | /) unary}
    def parse_term(self) -> FormulaNode:
        node = self.parse_unary()
        while self.current_token() and self.current_token().type == 'OP' and self.current_token().value in ('*', '/'):
            op = self.current_token().value
            self.advance()
            right = self.parse_unary()
            node = BinaryOpNode(op, node, right)
        return node

    # unary := (+ | -) unary | number | ref | ( expr )
    def parse_unary(self) -> FormulaNode:
        token = self.current_token()

        # Handle leading unary +/- sign (this is slightly complex because it's recursive)
        if token and token.type == 'OP' and token.value in ('+', '-'):
            op = token.value
            self.advance()
            # Unary sign binds tighter than binary operators, so we recurse to parse the next element as a factor
            operand = self.parse_unary() 
            return UnaryOpNode(op, operand)

        # Handle ( expr )
        if token and token.type == 'OP' and token.value == '(': 
            self.advance()
            node = self.parse_expression()
            self.expect('OP', ')') # Expect closing parenthesis
            return node

        # Handle number or reference
        if token and token.type == 'NUMBER':
            self.advance()
            try:
                return NumberNode(int(token.value) if '.' not in token.value else float(token.value))
            except ValueError: # Should not happen if regex is correct
                raise FormulaError(f"Invalid number format: {token.value}")

        if token and token.type == 'REF':
            self.advance()
            name = token.value.upper() # Store upper-cased name immediately

            # Validate reference: Must be valid sheet cell name (A-Z, 1-999, no leading zero for row)
            if not re.fullmatch(r'[A-Z][1-9]\d{0,2}', name):
                 # Check against stricter rules: one letter, 1-999, no leading zero
                col_match = re.match(r'[A-Z]+', name)
                row_str = name[len(col_match.group(0)):].lstrip('0')

                if not col_match or not row_str.isdigit() or int(row_str) < 1 or int(row_str) > 999:
                     raise FormulaError(f"Reference '{name}' is out of bounds or invalid format.")

            return ReferenceNode(name)

        # If none of the above match
        raise FormulaError("Unexpected token during parsing.")

    def parse(self) -> FormulaNode:
        # Start parsing from the lowest precedence level (expression)
        tree = self.parse_expression()

        # Ensure all input was consumed
        if self.current_token() is not None:
            raise FormulaError("Unexpected tokens remaining after parsing expression.")

        return tree

