        operand_val = evaluate(tree.operand, lookup)
        if isinstance(operand_val, ErrorValue):
            return operand_val # Propagate error

        # Unary + or -
        if tree.op == '+':
            return operand_val
        elif tree.op == '-':
            # Unary minus
            return -operand_val

    if isinstance(tree, BinaryOpNode):
        left_val = evaluate(tree.left, lookup)
        right_val = evaluate(tree.right, lookup)

        return _apply_op(tree.op, left_val, right_val)

    raise FormulaError("Unknown AST node type during evaluation.")

