            self._constraints = [('*',)]
            return

        self._constraints = []
        constraints = [c.strip() for c in spec.split(',')] 

        for constraint_str in constraints:
            if not constraint_str: continue # Allow trailing commas

            # Check for wildcard '*'
            if constraint_str == '*':
                self._constraints.append(('*',))
                continue

            # Regex to capture operator, version string, and optional trailing chars (like ~ or ^)
            # Supports: ==, !=, >=, <=, >, <, ^, ~
            # Handles operators with 1 or 2 chars.
            match = re.match(r'^(==|!=|>=|<=|>|<|~|\^)(.+)$', constraint_str)

            if match:
