                            upper_bound_str = f"0.{new_minor}.0"
                            upper_bound = Version(upper_bound_str)
                            self._constraints.append(('>=', target_v))
                            self._constraints.append(('<', upper_bound))
                    except ValueError as e:
                        raise ValueError(f"Invalid caret constraint '{constraint_str}': {e}")
                    continue
                elif op == '~':
                    # ~1.2.3 is >=1.2.3, <1.3.0
                    try:
                        target_v = Version(version_str)
                        # Increment patch
                        parts = [target_v.major, target_v.minor, target_v.patch + 1]
                        upper_bound_str = f"{parts[0]}.{parts[1]}.{parts[2]}"
                        upper_bound = Version(upper_bound_str)
                        # Add >=V
                        self._constraints.append(('>=', target_v))
                        # Add <(V.m+1.0)
                        self._constraints.append(('<', upper_bound))
                    except ValueError as e:
                        raise ValueError(f"Invalid tilde constraint '{constraint_str}': {e}")
                    continue
                else:
                    # Standard operators: ==, !=, >=, <=, >, <
                    try:
                        target_v = Version(version_str)
                        self._constraints.append((op, target_v))
                    except ValueError as e:
                        raise ValueError(f"Invalid version in constraint '{constraint_str}': {e}")
