    """Stores package releases and their dependencies."""

    def __init__(self):
        # Structure: { package_name: { Version_object: { dependency_name: Range_object, ... } } }
        self._packages: Dict[str, Dict[Version, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None) -> None:
        """Adds a release of a package, validating version and dependency specs."""

        # 1. Validate Version
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Invalid version string '{version_str}': {e}")

        # 2. Check for duplicates
        if name in self._packages and version in self._packages[name]:
            raise ValueError(f"Release {name}@{version_str} already exists in the index.")

        if name not in self._packages:
            self._packages[name] = {}

        release_data: Dict[str, Range] = {}

        # 3. Validate and store requirements
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    # Range constructor handles validation for empty spec as well
                    range_obj = Range(spec_str)
                    release_data[dep_name] = range_obj
                except ValueError as e:
                    raise ValueError(f"Invalid dependency specification for {name}@{version_str} on {dep_name}: {e}")

        # 4. Store the release
        self._packages[name][version] = release_data

    def versions(self, name: str) -> list[Version]:
        """Returns a list of known Versions for a package, newest first."""
        if name not in self._packages:
            return []

        versions_list = list(self._packages[name].keys())
        # Sort using the Version's natural comparison (< means older)
        versions_list.sort(reverse=True) 
        return versions_list

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns the dependency ranges for a specific release. Raises KeyError if not found."""
        if name not in self._packages:
            raise KeyError(f"Package '{name}' not found in index.")

        if version not in self._packages[name]:
            raise KeyError(f"Version {version} of package '{name}' not found in index.")

        return self._packages[name][version]

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds an index from a dictionary structure. Data format: {name: {version: {dep: spec, ...}, ...}, ...}"""
        index = cls()
        for name, versions_data in data.items():
            for version_str, requires in versions_data.items():
                # Note: We rely on add() to raise ValueError if version_str or specs are invalid
                try:
                    index.add(name, version_str, requires=requires)
                except ValueError as e:
                    # In a real scenario, we might log this instead of crashing, 
                    # but matching the strictness of add(), we let it propagate if necessary.
                    raise e
