                op = match.group(1)
                version_text = match.group(2)

                # Convert version text to Version object immediately to validate format
                try:
                    version_obj = Version(version_text)
                except ValueError as e:
                    raise ValueError(f"Invalid version format in constraint '{constraint_str}': {e}")

                # Handle specific range syntax parsing (e.g., ^ and ~)
                if op == '^':
                    # ^X.Y.Z is >=X.Y.Z and <(X+1).0.0 if X is not 0, or <X.(Y+1).0 if X=0 and Y is not 0, or <X.Y.(Z+1) if X=Y=0
                    base_version = version_obj
