                elif op == '!=':
                    self.constraints.append(('!=', version_obj))
                else:
                    # Standard operators: ==, >, >=, <, <=
                    self.constraints.append((op, version_obj))
            else:
                # Must be the catch-all '*' operator if it didn't match the pattern
                if constraint_str == '*':
                    self.constraints.append(('*', None))
                else:
                    raise ValueError(f"Unknown operator or invalid constraint format: '{constraint_str}'")

