class Range:
    """Represents a version range constraint."""
    def __init__(self, spec: str):
        if not isinstance(spec, str): 
            raise TypeError("Range must be initialized with a string.")

        self.original_spec = spec.strip()
        self.constraints = []
        self._parse_spec(self.original_spec)

    def _parse_spec(self, spec_str: str):
        """Parses the comma-separated specification string into individual constraints."""
        constraints_list = [c.strip() for c in spec_str.split(',')]

        if not spec_str.strip():
            self.constraints = [('*', None)] # Empty spec means 'any version'
            return

        for constraint_str in constraints_list:
            if not constraint_str: # Handles trailing commas like '>=1.0.0,'
                raise ValueError("Empty constraint found in range specification.")

            # Operators: ==, !=, >, >=, <, <=, ^, ~
            # Need to check for compound operators first
            op = None
            match = re.match(r"([=!<>~^]=?)\s*([0-9.]+)", constraint_str)

            if match:
                op = match.group(1)
                version_text = match.group(2)

                # Convert version text to Version object immediately to validate format
                try:
                    version_obj = Version(version_text)
                except ValueError as e:
                    raise ValueError(f"Invalid version format in constraint '{constraint_str}': {e}")

                # Handle specific range syntax parsing (e.g., ^ and ~)
                if op == '^':
                    # ^X.Y.Z is >=X.Y.Z and <(X+1).0.0 if X is not 0, or <X.(Y+1).0 if X=0 and Y is not 0, or <X.Y.(Z+1) if X=Y=0
                    base_version = version_obj
                    major, minor, patch = base_version.tuple_form

                    if major > 0:
                        upper_bound = Version(f"{major+1}.0.0")
                    elif minor > 0:
                        upper_bound = Version(f"{major}.{minor+1}.0")
                    else: # major=0, minor=0
                        upper_bound = Version(f"{major}.{minor}.{patch+1}")

                    # ^ means >= base, < next major component increase
                    self.constraints.append((op, version_obj, upper_bound))
                    continue # Skip standard logic

                elif op == '~':
                    # ~X.Y.Z is >=X.Y.Z and <X.(Y+1).0
                    base_version = version_obj
                    major, minor, patch = base_version.tuple_form

                    if patch < 2: # If patch is less than 2, increment minor
                         # e.g., ~1.2.3 -> >=1.2.3, <1.3.0
                        upper_bound = Version(f"{major}.{minor+1}.0")
                    else:
                        # This case is complex and usually relies on SemVer rules, but following the prompt's example:
                        # ~1.2.3 is >=1.2.3, <1.3.0. If patch >= 3, we assume the next minor change is the bound.
                        upper_bound = Version(f"{major}.{minor+1}.0")

                    self.constraints.append((op, version_obj, upper_bound))
                    continue # Skip standard logic

                elif op == '!=':
                    self.constraints.append(('!=', version_obj))
                else:
                    # Standard operators: ==, >, >=, <, <=
                    self.constraints.append((op, version_obj))
            else:
                # Must be the catch-all '*' operator if it didn't match the pattern
                if constraint_str == '*':
                    self.constraints.append(('*', None))
                else:
                    raise ValueError(f"Unknown operator or invalid constraint format: '{constraint_str}'")

    def __str__(self) -> str:
        # Returns the spec with all whitespace removed
        return self.original_spec.replace(' ', '')

    def __repr__(self) -> str:
        return f"Range('{self.original_spec}')"

    def contains(self, version: Version) -> bool:
        """Checks if the given Version satisfies all constraints in this range."""

        # If there are no constraints (shouldn't happen if spec is non-empty, but defensively),
        # we assume it matches if the original spec was empty.
        if not self.constraints and self.original_spec == "":
             return True

        for constraint in self.constraints:
            op = constraint[0]
            v_spec = constraint[1]
            v_upper = constraint[2] if len(constraint) > 2 else None

            match_found = False

            if op == '*':
                match_found = True
            elif op == '==':
                match_found = (version == v_spec)
            elif op == '!=':
                match_found = (version != v_spec)
            elif op == '>':
                match_found = (version > v_spec)
            elif op == '>=':
                match_found = (version >= v_spec)
            elif op == '<':
                match_found = (version < v_spec)
            elif op == '<=':
                match_found = (version <= v_spec)

            # Handle caret (^) and tilde (~) ranges which carry an upper bound
            elif op == '^' or op == '~':
                if version >= v_spec:
                    # Check upper bound if it exists
                    if v_upper and version < v_upper:
                        match_found = True
                    else:
                        # Fails upper bound check
                        match_found = False
                else:
                    # Fails lower bound check
                    match_found = False

            if not match_found:
                return False

        return True

    def __in__(self, version: Version) -> bool:
        return self.contains(version)

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)


