from typing import Dict, List, Optional
from .versions import Version, Range

class PackageIndex:
    """Repository for known package releases, mapping names to versions and storing dependency requirements."""
    def __init__(self):
        # Structure: {name: {version_string: {dependency_name: Range_object, ...}}}
        self._packages: Dict[str, Dict[str, Dict[str, Range]]] = {}

    def add(self, name: str, version: str, requires: Optional[Dict[str, str]] = None) -> None:
        """Adds a release of a package to the index."""
        if name in self._packages and version in self._packages[name]:
            raise ValueError(f"Package {name} version {version} already exists in the index.")

        validated_requirements: Dict[str, Range] = {}
        if requires:
            for dep_name, spec in requires.items():
                try:
                    validated_requirements[dep_name] = Range(spec)
                except ValueError as e:
                    raise ValueError(f"Bad dependency specification '{spec}' for {name}@{version} in dictionary data: {e}")

        if name not in self._packages:
            self._packages[name] = {}
        self._packages[name][version] = validated_requirements

    def versions(self, name: str) -> List[Version]:
        """Returns the list of known Version objects for a package, newest first."""
        if name not in self._packages:
            return []

        versions_map = self._packages[name]
        # Convert version strings to Version objects
        version_objects = [Version(v_str) for v_str in versions_map.keys()]

        # Sort newest first
        return sorted(version_objects, reverse=True)

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns the dependency requirements for a specific version of a package."""
        if name not in self._packages or version.text not in self._packages[name]:
            raise KeyError(f"Version {version.text} of package {name} not found in index.")

        return self._packages[name][version.text]

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds a PackageIndex from a dictionary structure."""
        index = cls()
        for name, versions_data in data.items():
            for version_str, requires_dict in versions_data.items():
                # Convert string specs to Range objects during loading
                validated_requirements: Dict[str, Range] = {}
                for dep_name, spec in requires_dict.items():
                    try:
                        validated_requirements[dep_name] = Range(spec)
                    except ValueError as e:
                        raise ValueError(f"Bad dependency specification '{spec}' for {name}@{version_str} in dictionary data: {e}")

                index._packages[name][version_str] = validated_requirements
        return index

