class ParseError(ValueError):
    pass

# --- Utility Functions for Validation/Conversion ---

def safe_int(value: Any, default: int = 0) -> int:
    if value is None: return default
    if isinstance(value, str):
        if value in ('-', ''): return default
        try:
            return int(value)
        except ValueError:
            pass
    try:
        return int(value)
    except (ValueError, TypeError):
        return default

def safe_float(value: Any) -> Optional[float]:
    if value is None: return None
    if isinstance(value, str) and value.strip() in ('-', ''):
        return None
    try:
        f = float(value)
        return f if f >= 0 else None
    except (ValueError, TypeError):
        return None

# --- Normalization Function ---

def normalize(time_obj: datetime, client: str, method: str, path: str, status: Any, size: Any, latency_ms: Any) -> 'Record':
    """Applies all validation and rules to convert raw fields into a normalized Record."""

    # 1. Time Validation & Conversion (Must be timezone-aware UTC)
    if time_obj.tzinfo is None or time_obj.tzinfo.utcoffset(time_obj) is None:
        raise ParseError(f"Time must be timezone-aware. Received: {time_obj}")
    # Convert to UTC
    time_utc = time_obj.astimezone(timezone.utc)

    # 2. Client Validation
    if not isinstance(client, str) or not client.strip():
        raise ParseError("Client field must be a non-empty string.")
    client_str = client.strip()

    # 3. Method Validation
    if not isinstance(method, str) or not method.strip() or not method.strip().isalpha() or not method.strip().isupper():
        # The requirement states 'ASCII letters', so checking isalpha() and isupper() after ensuring it's a string is a good start.
        # We ensure it's upper-cased here as per rule.
        method_upper = method.upper()
        if not method_upper.isalpha() or not method_upper:
             raise ParseError("Method field must be a non-empty string of ASCII letters.")
        method_str = method_upper
    else:
        method_str = method.upper()

    # 4. Path Validation & Cleanup
    if not isinstance(path, str) or not path.startswith('/'):
        raise ParseError("Path must start with '/'.")

    # Remove everything from the first '?' or '#' onwards
    path_base = path.split('?')[0].split('#')[0]

    # Collapse runs of '/' into one
    path_cleaned = re.sub(r'/+', '/', path_base)

    # 5. Status Validation
    status_int = safe_int(status)
    if not (100 <= status_int <= 599):
        raise ParseError(f"Status code {status} is out of range (100-599).")

    # 6. Size Validation
    size_int = safe_int(size) # safe_int handles None and '-' as 0

    # 7. Latency Validation
    latency_float = safe_float(latency_ms)

    return Record(
        time=time_utc,
        client=client_str,
        method=method_str,
        path=path_cleaned,
        status=status_int,
        size=size_int,
        latency_ms=latency_float
    )

# --- Line Parsing Dispatcher ---
def parse_line(line: str, fmt: str = 'auto') -> Tuple[Optional['Record'], Optional[ParseError]]:
    """Delegates line parsing to the appropriate parser based on format or heuristic."""

    line = line.strip()
    if not line: 
        return None, None

    if fmt == 'auto':
        if line.startswith('{'):
            # Heuristic: JSON starts with '{'
            try:
                # Attempt to parse JSON to see if it's valid JSON structure
                data = json.loads(line)
                if isinstance(data, dict):
                    # Assuming parse_jsonl handles the actual parsing and normalization logic
                    # Here we just dispatch; the actual parsing/error handling is in parse_jsonl/parse_clf
                    return parse_jsonl(line, fmt='jsonl') 
                else:
                    # It's JSON, but not an object
                    return None, ParseError("JSON line did not parse to an object.")
            except json.JSONDecodeError:
                # Not valid JSON, treat as CLF attempt
                pass
        # If not JSON starting with '{' or JSON parsing failed, treat as CLF
        return parse_clf(line, fmt='clf')

    elif fmt == 'clf':
        return parse_clf(line, fmt='clf')
    elif fmt == 'jsonl':
        return parse_jsonl(line, fmt='jsonl')
    else:
        raise ValueError(f"Unsupported format '{fmt}'. Must be 'auto', 'clf', or 'jsonl'.")

